<?php
namespace App\Http\Middleware;
use App\Application\Sso\CentralLoginUrl;use App\Application\Sso\PermissionService;use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use RuntimeException;
class EnsureEmsAccess { public function handle(Request $request,Closure $next){$user=$request->user();if(!$user)return redirect()->away(app(CentralLoginUrl::class)->loginUrl());if(app()->environment('testing')&&!$user->sso_user_id)return$next($request);if(!$user->sso_user_id){auth()->logout();$request->session()->invalidate();return redirect()->away(app(CentralLoginUrl::class)->loginUrl());}$service=app(PermissionService::class);$age=now()->timestamp-(int)$request->session()->get('sso.permissions_synced_at',0);if($age>=config('gpha_sso.permission_cache_seconds')){try{$map=$service->fetch((string)$user->sso_user_id,(string)config('gpha_sso.module_id'));$request->session()->put(['sso.permissions'=>$map,'sso.permissions_synced_at'=>now()->timestamp]);}catch(RuntimeException $e){Log::error('EMS permission refresh failed',['user_id'=>$user->id,'reason'=>$e->getMessage()]);if(!$service->hasAny())return response()->view('errors.sso-access',['title'=>'Central Login is unavailable','message'=>$e->getMessage()],503);}}if(!$service->hasAny())abort(403,'Your account has no EMS permissions.');return$next($request);} }
